const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = $input.all().map(i => i.json).filter(r => r.post_no);
if (!rows.length) {
  return [{ json: { text: '🦊 Итог недели: свежих постов в канале старше 2 суток нет — роликам не за что зацепиться.' } }];
}
const lines = rows.map((r, k) =>
  `${k + 1}. <b>${esc(r.title)}</b> — ${r.views} просмотров, ${r.reactions} реакций\nhttps://t.me/ryzh_trener/${r.post_no}` +
  (r.ryzh_post_id ? ` · пост #${r.ryzh_post_id}` : ''));
const text = '🦊 <b>Тема недели для ролика</b>\n\n' + lines.join('\n\n') +
  '\n\nРолик ставит проблему, пост её решает: подпись ролика — «Подробности — в канале Рыжа, ссылка в шапке», ' +
  'в сторис — стикер-ссылка на пост. Связку записать в content_links (reel_no, ryzh_post_id).';
return [{ json: { text } }];
